// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 b) internal {
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(b <= address(this).balance);
        uint before = address(this).balance;
        try c.deposit{value: b}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint finalBal = address(this).balance;
        assertTrue(finalBal <= before);
    }

    function testFuzz_run(uint256 b) public {
        _run(b);
    }

    receive() external payable {}
}
